import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    preamble = []
    columns = None
    for record in reader:
        if len(record) == 2 and all(field.strip() for field in record):
            columns = record
            break
        preamble.append(record)

    if columns is None:
        columns = []
        rows = preamble
    else:
        rows = list(reader)

    width = max(len(columns), max((len(row) for row in rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"column_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
